package __PKG__;

import java.util.ArrayList;
import java.util.List;

/** Runs code a number of server ticks later. Generated by Minecraft Builder. */
public final class Scheduler {
    private record Task(long due, Runnable run) {}

    private static final List<Task> TASKS = new ArrayList<>();
    private static long tick = 0;

    private Scheduler() {}

    public static synchronized void later(int ticks, Runnable run) {
        TASKS.add(new Task(tick + Math.max(1, ticks), run));
    }

    public static void tick() {
        List<Task> due = new ArrayList<>();
        synchronized (Scheduler.class) {
            tick++;
            TASKS.removeIf(t -> {
                if (t.due() <= tick) {
                    due.add(t);
                    return true;
                }
                return false;
            });
        }
        for (Task t : due) {
            try {
                t.run().run();
            } catch (Throwable e) {
                __MAIN__.LOGGER.error("Error in delayed task", e);
            }
        }
    }
}
